function renderGarage(refreshPreview=true){updateWallet();let classes={sloop:'VELEIRO',catamaran:'CATAMARÃ',racer:'REGATA',trimaran:'TRIMARÃ',caravel:'HISTÓRICO',viking:'GUERRA',baleeira:'AMAZÔNIA',bigdog:'CAPITÂNIA',solar:'EGITO ANTIGO'},equipped=b=>save.owned.includes(b.id)?styledBoat(b):b;$('#boatGrid').innerHTML=BOATS.map((b,index)=>{let owned=save.owned.includes(b.id),sel=save.selected===b.id,image=renderBoatCardImage(b),stats=equipped(b),speedPct=stats.speed/78*100,turnPct=stats.turn/3.2*100;return `<article class="boat-card ${sel?'selected':''} ${owned?'':'locked'}" data-id="${b.id}"><header><span>#${String(index+1).padStart(2,'0')}</span><b>${classes[b.type]||'EMBARCAÇÃO'}</b></header><div class="boat-visual"><img src="${image}" alt="Modelo 3D de ${b.name}"><em>${sel?'EM USO':owned?'ADQUIRIDO':'BLOQUEADO'}</em></div><div class="boat-card-info"><h3>${b.name}</h3><div class="ship-stat"><span>VELOCIDADE <b>${stats.speed}</b></span><i><u style="width:${Math.min(100,speedPct)}%"></u></i></div><div class="ship-stat"><span>MANOBRA <b>${Math.round(stats.turn*10)}</b></span><i><u style="width:${Math.min(100,turnPct)}%"></u></i></div><footer class="${owned?'owned':'price'}">${owned?(sel?'✓ SELECIONADO':'SELECIONAR'):`${b.price} <span>🪙</span>`}</footer></div></article>`}).join('');document.querySelectorAll('.boat-card').forEach(card=>card.onclick=()=>chooseBoat(card.dataset.id));if(refreshPreview)setPreview()}
