const UPGRADES=[{id:'speed',icon:'⚡',name:'VELOCIDADE',desc:'+2 máxima · instala propulsores metálicos',prices:[35,70,105,150,210]},{id:'accel',icon:'🚀',name:'ACELERAÇÃO',desc:'Retoma velocidade rapidamente após largar ou bater',prices:[40,80,125,180,250]},{id:'draft',icon:'💨',name:'OTIMIZAÇÃO DE VÁCUO',desc:'Aumenta o impulso recebido atrás dos adversários',prices:[50,100,155,220,300]},{id:'turn',icon:'🧭',name:'LEME DE COMPETIÇÃO',desc:'Curvas mais fechadas com menor perda de velocidade',prices:[45,90,140,200,275]},{id:'hull',icon:'🛡️',name:'CASCO REFORÇADO',desc:'Reduz a perda de velocidade em colisões',prices:[55,110,170,240,330]},{id:'capacity',icon:'🔋',name:'CAPACIDADE DE TURBO',desc:'Armazena uma carga adicional de turbo por nível',prices:[80,160,250,360,500]},{id:'regen',icon:'🔥',name:'REGEN. TURBO',desc:'Recarga mais rápida · adiciona bobinas luminosas',prices:[45,90,135,190,260]},{id:'magnet',icon:'🧲',name:'ÍMÃ DE RECOMPENSAS',desc:'Atrai moedas próximas sem passar exatamente sobre elas',prices:[50,100,160,230,320]},{id:'coins',icon:'🪙',name:'MOEDAS EM DOBRO',desc:'Multiplicador · adiciona troféus e acabamento dourado',prices:[60,120,180,250,340]}];
function upgradeEffectLabel(id,lv){let e=WindUpgrades.effects({[id]:lv});return({speed:`+${e.speedBonus} VELOCIDADE`,accel:`+${e.accelBonus} ACELERAÇÃO`,draft:`+${e.draftBonus.toFixed(1)} VÁCUO`,turn:`+${e.turnBonus.toFixed(2)} MANOBRA`,hull:`+${e.resistanceBonus} RESISTÊNCIA`,capacity:`${e.maxTurbos} CARGAS`,regen:`RECARGA EM ${e.regenSeconds}s`,magnet:`RAIO ${e.magnetRadius}m`,coins:`MOEDAS ×${e.coinMultiplier}`}[id]||'')}
function renderUpgrades(){let u=levels();updateWallet();$('#upgradeBoatName').textContent=selectedBoat().name;$('#upgradeGrid').innerHTML=UPGRADES.map(x=>{let lv=WindUpgrades.level(u[x.id]),cost=x.prices[lv],max=lv>=5;return `<article class="upgrade-card"><div class="ico">${x.icon}</div><h3>${x.name}</h3><p>${x.desc}</p><small class="upgrade-effect">${upgradeEffectLabel(x.id,lv)}</small><div class="levels">${[0,1,2,3,4].map(i=>`<i class="${i<lv?'on':''}"></i>`).join('')}</div><button data-upgrade="${x.id}" ${max?'disabled':''}>${max?'MÁXIMO':cost+' 🪙'}</button></article>`}).join('');document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>buyUpgrade(b.dataset.upgrade))}
async function buyUpgrade(id){let u=levels(),x=UPGRADES.find(v=>v.id===id),lv=u[id]||0,cost=x?.prices[lv];if(!x||lv>=5||save.coins<cost)return;try{if(cloudEnabled)await cloudPurchase('upgrade',save.selected,id);else{save.coins-=cost;u[id]=lv+1}for(let key of boatCardCache.keys())if(key.startsWith(save.selected+':'))boatCardCache.delete(key);persist();renderUpgrades();updateWallet()}catch(error){setStatus(error.message?.includes('insufficient')?'Saldo insuficiente.':'Upgrade não autorizado.','error')}}
function setStatus(text,kind=''){$('#netStatus').textContent=text;$('#netStatus').className=kind}function lobbyReady(){return net.host&&net.players.size>=1&&Array.from(net.players.values()).every(p=>p.ready)}function updateLobbyControls(){let b=$('#start');if(gameMode!=='multi'){b.textContent='INICIAR CORRIDA';b.disabled=false;return}if(net.host){let ready=lobbyReady();b.textContent=ready?'INICIAR CORRIDA':net.players.size?'AGUARDANDO PREPARADOS':'AGUARDANDO JOGADORES';b.disabled=!ready}else{b.textContent=net.ready?'CANCELAR PREPARO':'FICAR PREPARADO';b.disabled=!net.connected||!net.ownerId}}function showPlayers(){let active=net.connected||net.channel||net.host,all=new Map(active?[[net.myId,{id:net.myId,name:save.nickname,ready:net.host||net.ready}],...Array.from(net.players.values()).map(p=>[p.id,p])]:[]),ps=Array.from(all.values());ps.sort((a,b)=>(a.id===net.ownerId?-1:b.id===net.ownerId?1:WindSecurity.nickname(a.name).localeCompare(WindSecurity.nickname(b.name))));$('#playerCount').textContent=ps.length;WindSecurity.renderPlayers($('#playerList'),ps,net.myId,net.ownerId);updateLobbyControls();if(net.host&&net.publicToken)heartbeatPublicRoom()}
async function lobbyCall(body){let session=await ensureOnlineIdentity(),headers={Authorization:`Bearer ${session.access_token}`,apikey:SUPABASE_KEY},options=body?{method:'POST',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify(body),keepalive:true}:{headers};return WindSecurity.fetchJson(LOBBY_URL,options,8000)}
function renderPublicRooms(rooms){let box=$('#publicRooms');box.innerHTML='';if(!rooms.length){let empty=document.createElement('small');empty.textContent='NENHUMA SALA PÚBLICA AGORA';box.append(empty);return}rooms.forEach(room=>{let card=document.createElement('button');card.className='public-room-card';let info=document.createElement('span'),name=document.createElement('strong'),meta=document.createElement('small'),join=document.createElement('b');name.textContent=room.host_name;meta.textContent=`${room.code} · ${room.player_count}/${room.max_players} JOGADORES`;join.textContent=room.player_count>=room.max_players?'CHEIA':'ENTRAR';info.append(name,meta);card.append(info,join);card.disabled=room.player_count>=room.max_players;card.onclick=()=>{$('#roomCode').value=room.code;$('#copyRoom').disabled=false;joinRoom()};box.append(card)})}
async function refreshPublicRooms(){let box=$('#publicRooms');box.innerHTML='<small>BUSCANDO SALAS...</small>';try{let data=await lobbyCall();renderPublicRooms(data.rooms||[])}catch{box.innerHTML='<small>LOBBY INDISPONÍVEL · TENTE ATUALIZAR</small>'}}
async function registerPublicRoom(){if(net.host&&$('#publicRoom').checked)refreshPublicRooms()}
function startRoomHeartbeat(){clearInterval(net.lobbyTimer);heartbeatRoom();net.lobbyTimer=setInterval(heartbeatRoom,45000)}
function heartbeatRoom(){if(net.room&&net.myId)lobbyCall({action:'heartbeat',code:net.room}).catch(()=>{})}
function unpublishPublicRoom(){if(net.host&&net.room)lobbyCall({action:'unpublish',code:net.room}).catch(()=>{});net.publicToken=''}
function removePublicRoom(){let code=net.room;clearInterval(net.lobbyTimer);net.lobbyTimer=null;net.publicToken='';if(!code||!net.myId)return;lobbyCall({action:'leave',code}).catch(()=>{})}
function netError(joining=false){clearTimeout(net.timeout);net.connected=false;setStatus(joining?'Sala não encontrada ou o dono saiu. Atualize a lista e tente novamente.':'Falha no servidor multiplayer. Tente criar a sala novamente.','error');if(joining)$('#start').disabled=true}
function beginRemoteRace(d){if(!d?.raceId||d.raceId===net.lastRaceId||!net.ownerId||d.id!==net.ownerId)return;net.lastRaceId=d.raceId;totalLaps=Number(d.laps)||3;$('#lapSelect').value=String(totalLaps);setStatus('PARTIDA INICIADA PELO DONO!','online');start(true)}
function syncPresence(){if(!net.channel)return;let presences=Object.values(net.channel.presenceState()).flat(),players=new Map(),ownerId=net.host?net.myId:'',ownerPresence=null;for(let p of presences){if(!p?.id||typeof p.id!=='string')continue;if(p.owner){ownerId=p.id;ownerPresence=p}if(p.id!==net.myId)players.set(p.id,{id:p.id,name:WindSecurity.nickname(p.name),boat:BOATS.some(b=>b.id===p.boat)?p.boat:'vento',skin:SKINS.some(s=>s.id===p.skin)?p.skin:'classica',ready:!!p.ready})}let ownerLeft=!net.host&&net.connected&&!ownerId;net.ownerId=ownerId;net.players=players;if(!net.host&&ownerId){net.connected=true;clearTimeout(net.timeout);$('#leaveRoom').disabled=false;if(ownerPresence?.phase==='starting'&&ownerPresence.raceId)beginRemoteRace({type:'start',id:ownerId,raceId:ownerPresence.raceId,laps:ownerPresence.laps});else if(state==='menu')setStatus(net.ready?'Você está preparado. Aguardando o dono iniciar.':'Conectado! Aperte FICAR PREPARADO.','online')}else if(ownerLeft){setTimeout(()=>leaveRoom('O dono saiu da sala. Você voltou ao modo Solo.'),0);return}showPlayers()}
function hostAcceptState(d){
  let r=racers.find(x=>x.netId===d.id&&x.remote);if(!r)return;
  let now=performance.now(),dt=Math.min(.5,Math.max(.05,(now-(r.lastNetAt||now-80))/1000)),previous=r.target||r,distance=Math.hypot(d.x-(r.lastNetX??previous.x),d.z-(r.lastNetZ??previous.z)),limit=(r.spec.speed+28)*dt+12;
  r.lastNetAt=now;if(distance>limit||Math.abs(angleDiff(previous.a,d.a))>2.8)return;r.lastNetX=d.x;r.lastNetZ=d.z;
  let cp=previous.cp,lap=previous.lap,done=!!previous.done,finishOrder=previous.finishOrder||0,target=TRACK[cp],checkpointRadius=cp===0?48:30,newlyDone=false;
  if(!done&&Math.hypot(target.x-d.x,target.y-d.z)<checkpointRadius){let next=WindRaceRules.advanceCheckpoint(cp,lap,totalLaps,TRACK.length);cp=next.cp;lap=next.lap;done=next.done;newlyDone=done;if(done)finishOrder=Math.max(0,...racers.map(x=>x.finishOrder||x.target?.finishOrder||0))+1}
  let score=done?(totalLaps+1)*TRACK.length:(lap-1)*TRACK.length+cp+1-Math.hypot(TRACK[cp].x-d.x,TRACK[cp].y-d.z)/900;
  r.target={x:d.x,z:d.z,a:d.a,spd:THREE.MathUtils.clamp(d.spd,-16,r.spec.speed+60),cp,lap,score,done,finishOrder,receivedAt:performance.now()};
  coins3d.forEach((coin,index)=>{if(!coin.taken&&Math.hypot(coin.x-d.x,coin.z-d.z)<7){coin.taken=true;coin.mesh.visible=false;broadcast({type:'coinAward',id:net.myId,playerId:d.id,index,value:1})}});
  if(bonusChest&&!bonusChest.taken&&Math.hypot(bonusChest.x-d.x,bonusChest.z-d.z)<7){bonusChest.taken=true;bonusChest.mesh.visible=false;broadcast({type:'chestAward',id:net.myId,playerId:d.id,value:bonusChest.bonus})}
  broadcast({type:'snapshot',id:net.myId,playerId:d.id,...r.target});if(newlyDone)announceFinish(r,r.target)
}
function handleNet(d){
  if(!WindSecurity.validPacket(d)||d.id===net.myId)return;let now=performance.now();net.packetTimes=net.packetTimes.filter(t=>now-t<1000);if(net.packetTimes.length>90)return;net.packetTimes.push(now);
  if(d.type==='start'){if(d.id===net.ownerId)beginRemoteRace(d)}
  else if(d.type==='state'){if(net.host)hostAcceptState(d)}
  else if(d.type==='snapshot'&&d.id===net.ownerId){let r=racers.find(x=>x.netId===d.playerId);if(r){if(r.local){if(Math.hypot(r.x-d.x,r.z-d.z)>8){r.x=THREE.MathUtils.lerp(r.x,d.x,.2);r.z=THREE.MathUtils.lerp(r.z,d.z,.2)}r.cp=d.cp;r.lap=d.lap;r.score=d.score;if(d.done&&(state==='race'||state==='count')){r.done=true;r.finishOrder=d.finishOrder||0;finish(r.finishOrder)}}else r.target={...d,receivedAt:performance.now()}}}
  else if(d.type==='finishResult'&&d.id===net.ownerId){let r=racers.find(x=>x.netId===d.playerId);if(r){r.done=true;r.finishOrder=d.finishOrder;r.score=d.score;if(r.local&&(state==='race'||state==='count'))finish(d.finishOrder)}}
  else if(d.type==='coinAward'&&d.id===net.ownerId){let c=coins3d[d.index];if(c){c.taken=true;c.mesh.visible=false}if(d.playerId===net.myId){net.authoritativeCoins+=Math.max(0,Math.min(8,Number(d.value)||0));raceCoins=net.authoritativeCoins;$('#raceCoins').textContent=raceCoins}}
  else if(d.type==='chestAward'&&d.id===net.ownerId){if(bonusChest){bonusChest.taken=true;bonusChest.mesh.visible=false}if(d.playerId===net.myId){net.authoritativeCoins+=Math.max(0,Math.min(100,Number(d.value)||0));raceCoins=net.authoritativeCoins;$('#raceCoins').textContent=raceCoins}}
}
function broadcast(data){return net.connected&&net.channel?net.channel.send({type:'broadcast',event:'game',payload:data}):Promise.resolve('not_connected')}
function announceFinish(r,data=r){if(gameMode!=='multi'||!net.host||!r)return;let payload={type:'finishResult',id:net.myId,playerId:r.netId,finishOrder:data.finishOrder||r.finishOrder||1,score:data.score||r.score||0};[0,300,900].forEach(delay=>setTimeout(()=>broadcast(payload),delay))}
function connectRealtime(code,asHost){let attempt=net.attempt;net.host=asHost;net.ready=asHost;net.room=code;net.ownerId=asHost?net.myId:'';net.channel=realtimeClient.channel('wind-racer-'+code,{config:{private:true,broadcast:{self:false,ack:true},presence:{key:net.myId}}});net.channel.on('broadcast',{event:'game'},({payload})=>handleNet(payload)).on('presence',{event:'sync'},syncPresence).subscribe(async status=>{if(attempt!==net.attempt)return;if(status==='SUBSCRIBED'){net.connected=asHost;await net.channel.track({id:net.myId,name:save.nickname,boat:save.selected,skin:save.skinByBoat[save.selected]||'classica',ready:asHost,owner:asHost,phase:'lobby',raceId:'',laps:0});startRoomHeartbeat();$('#leaveRoom').disabled=false;if(asHost){clearTimeout(net.timeout);setStatus(`SALA ${code} — aguardando jogadores preparados.`,'online');showPlayers();await registerPublicRoom()}else{net.timeout=setTimeout(()=>{if(!net.ownerId)netError(true)},6500)}}else if(status==='CHANNEL_ERROR'||status==='TIMED_OUT'){netError(!asHost)}})}
async function createRoom(){disconnectNet();save.nickname=WindSecurity.nickname($('#nickname').value,save.nickname);$('#nickname').value=save.nickname;persist();let code=Math.random().toString(36).slice(2,7).toUpperCase();$('#roomCode').value=code;$('#copyRoom').disabled=false;setStatus('Criando sala segura...');try{await ensureOnlineIdentity();net.publicToken=crypto.randomUUID();await lobbyCall({action:'register',code,token:net.publicToken,hostName:save.nickname,isPublic:$('#publicRoom').checked});connectRealtime(code,true)}catch(error){setStatus(error.message,'error')}}
async function joinRoom(){disconnectNet();save.nickname=WindSecurity.nickname($('#nickname').value,save.nickname);$('#nickname').value=save.nickname;persist();let code=$('#roomCode').value.trim().toUpperCase().replace(/[^A-Z0-9]/g,'');$('#roomCode').value=code;if(code.length!==5)return setStatus('O código da sala deve ter 5 letras ou números.','error');$('#start').disabled=true;setStatus(`Conectando à sala segura ${code}...`);try{await ensureOnlineIdentity();await lobbyCall({action:'join',code,nickname:save.nickname});connectRealtime(code,false)}catch(error){setStatus(error.message,'error');$('#start').disabled=false}}
function disconnectNet(){net.attempt++;clearTimeout(net.timeout);net.timeout=null;removePublicRoom();if(net.channel){net.channel.untrack().catch(()=>{});realtimeClient.removeChannel(net.channel).catch(()=>{})}net.channel=null;net.connected=false;net.ready=false;net.players.clear();net.host=false;net.ownerId='';net.lastRaceId='';$('#leaveRoom').disabled=true;$('#copyRoom').disabled=!$('#roomCode').value.trim();showPlayers()}
async function toggleReady(){if(gameMode!=='multi'||net.host||!net.channel||!net.connected)return;net.ready=!net.ready;updateLobbyControls();setStatus(net.ready?'Você está preparado. Aguardando o dono iniciar.':'Preparo cancelado. Confirme novamente quando estiver pronto.',net.ready?'online':'');try{await net.channel.track({id:net.myId,name:save.nickname,boat:save.selected,skin:save.skinByBoat[save.selected]||'classica',ready:net.ready,owner:false,phase:'lobby',raceId:'',laps:0})}catch{net.ready=!net.ready;setStatus('Não foi possível atualizar seu preparo. Tente novamente.','error');updateLobbyControls()}}
async function copyRoomCode(){let code=$('#roomCode').value.trim().toUpperCase();if(!code)return;try{await navigator.clipboard.writeText(code)}catch{$('#roomCode').select();document.execCommand('copy')}setStatus(`CÓDIGO ${code} COPIADO!`,'online');let b=$('#copyRoom'),old=b.textContent;b.textContent='COPIADO ✓';setTimeout(()=>b.textContent=old,1600)}
