const SOLO_RIVALS={easy:[{name:'NINA',boat:'vento'},{name:'TICO',boat:'vento'},{name:'PIP',boat:'coral'},{name:'YARA',boat:'baleeira'},{name:'BENTO',boat:'coral'},{name:'LUA',boat:'vento'}],medium:[{name:'NOX',boat:'coral'},{name:'PIP',boat:'tempestade'},{name:'KAIRA',boat:'espectro'},{name:'VASCO',boat:'caravela'},{name:'RAGNAR',boat:'viking'},{name:'YARA',boat:'baleeira'}],hard:[{name:'KAIRA',boat:'espectro'},{name:'BIGDOG',boat:'bigdog'},{name:'NOX',boat:'tempestade'},{name:'VASCO',boat:'caravela'},{name:'RAGNAR',boat:'viking'},{name:'YARA',boat:'espectro'}]},AI_TUNE={easy:{speed:.72,accel:.72,turbo:.012},medium:{speed:.88,accel:.86,turbo:.035},hard:{speed:1.04,accel:1.02,turbo:.065}};
function reset(){racers.forEach(r=>{scene.remove(r.mesh);scene.remove(r.nameTag)});spray.forEach(s=>scene.remove(s.mesh));racers=[];spray=[];raceCoins=0;turboRegen=0;spawnCoins();spawnBonusChest();let soloRivals=SOLO_RIVALS[difficulty]||SOLO_RIVALS.medium,entries=gameMode==='multi'?[{id:net.myId,name:save.nickname,boat:save.selected,skin:save.skinByBoat[save.selected]||'classica',local:true},...Array.from(net.players.values()).map(p=>({id:p.id,name:p.name,boat:p.boat,skin:p.skin,remote:true}))]:[{id:net.myId,name:save.nickname,boat:save.selected,local:true},...soloRivals.map((v,i)=>({id:'ai'+i,name:v.name,boat:v.boat,ai:true}))],slots=entries.map(e=>e.id).sort();entries.forEach((e,i)=>{let raw=BOATS.find(b=>b.id===e.boat)||BOATS[0],remoteSkin=e.remote?skinForBoat(raw.id,e.skin):null,spec=e.local?styledBoat(raw):e.remote?{...applySkinToBoat(raw,remoteSkin),upgradeLevels:{}}:raw,model=makeSailboat(spec,i?0.92:1),u=e.local?levels():{speed:0,regen:0,coins:0},slot=gameMode==='multi'?slots.indexOf(e.id):i,tune=e.ai?(AI_TUNE[difficulty]||AI_TUNE.medium):{speed:1,accel:1,turbo:0};racers.push({x:-24+slot*8,z:145+(slot%2)*15,a:Math.PI,spd:0,cp:1,lap:1,done:false,finishOrder:0,turboTime:0,turbos:3,draft:0,draftBurst:0,draftCooldown:0,windBoost:0,offCourseTime:0,netSamples:[],score:0,ai:!!e.ai,aiTurbo:tune.turbo,remote:!!e.remote,local:!!e.local,netId:e.id,color:spec.color,name:e.name,mesh:model,nameTag:makeNameTag(e.name,!!e.local),spec:{...spec,speed:(spec.speed+u.speed*2)*tune.speed,accel:spec.accel*tune.accel},up:u,target:null,collisionCd:0})});elapsed=0;updateMeshes();updateWallet()}
async function start(fromNet=false){
  initAudio();
  if(!fromNet){totalLaps=Number($('#lapSelect').value)||3;save.laps=totalLaps;persist();syncCloudLoadout()}
  if(gameMode==='multi'&&!fromNet){
    if(!net.channel||!net.connected)return setStatus('Crie ou entre em uma sala primeiro.','error');
    if(!net.host)return setStatus('Apenas o anfitrião inicia a corrida.','error');
    if(!lobbyReady())return setStatus(net.players.size?'Todos os membros precisam ficar PREPARADOS.':'Entre com pelo menos mais um jogador para iniciar.','error');
    let raceId=crypto.randomUUID(),packet={type:'start',id:net.myId,raceId,laps:totalLaps};net.lastRaceId=raceId;$('#start').disabled=true;setStatus('INICIANDO PARTIDA PARA TODOS...','online');
    let results=await Promise.allSettled([net.channel.track({id:net.myId,name:save.nickname,boat:save.selected,skin:save.skinByBoat[save.selected]||'classica',ready:true,owner:true,phase:'starting',raceId,laps:totalLaps}),broadcast(packet)]),delivered=results.some(r=>r.status==='fulfilled'&&r.value==='ok');
    if(!delivered){net.lastRaceId='';updateLobbyControls();setStatus('Não foi possível avisar os jogadores. Tente iniciar novamente.','error');return}
    unpublishPublicRoom();await new Promise(resolve=>setTimeout(resolve,180));
  }
  reset();currentRaceId=null;
  if(cloudEnabled){let{data,error}=await realtimeClient.rpc('wind_begin_race',{p_mode:gameMode==='multi'?'multi':gameMode==='ghost'?'ghost':gameMode==='championship'?'championship':'solo',p_laps:totalLaps,p_room_code:gameMode==='multi'?net.room:null});if(!error)currentRaceId=data}
  state='count';countUntil=performance.now()+3600;$('#menu').classList.add('hidden');$('#garage').classList.add('hidden');$('#upgrades').classList.add('hidden');$('#tutorial').classList.add('hidden');$('#progression').classList.add('hidden');$('#result').classList.add('hidden');$('#pause').classList.add('hidden');$('#hud').classList.remove('hidden');$('#mobileControls').classList.toggle('hidden',!isMobile)
}
